"""Deterministic unit tests for the stdlib-only review-panel engine. No CLI is spawned.

The engine lives at ``skills/review-panel/review_panel.py``. That directory name has a
hyphen, so it is NOT importable as a package; the directory goes on ``sys.path`` and the
module is imported by its own name, the way the plan-duel suite reaches ``plan_duel``.
The CLI tests run the entry point as a subprocess by an ABSOLUTE path derived from THIS
file, so the suite runs from any working directory.
"""

import concurrent.futures
import copy
import errno
import hashlib
import html
from html.parser import HTMLParser
import json
import threading
import contextlib
import os
import shutil
import stat
import pathlib
import random
import re
import subprocess
import sys
import tempfile
import unittest
from dataclasses import replace
from pathlib import Path
from unittest import mock

_ENGINE_DIR = Path(__file__).resolve().parent.parent / "skills" / "review-panel"
if str(_ENGINE_DIR) not in sys.path:
    sys.path.insert(0, str(_ENGINE_DIR))

import review_panel  # noqa: E402

_ENGINE = _ENGINE_DIR / "review_panel.py"


def _capture(call):
    """Run an in-process CLI call and return its exit code with what it wrote to stderr.
    The engine reports refusals there, and a test asserting on a refusal's WORDS has to
    read them from somewhere."""
    import io
    err = io.StringIO()
    with contextlib.redirect_stderr(err):
        code = call()
    return code, err.getvalue()


def _run(*args, cwd=None, env=None):
    """Run the entry point cross-platform (never a shebang / exec-bit script).

    ``env`` is merged over this process's own, which is how a test steers a MINTED run
    directory into its own temporary tree: the engine mints under the host's temporary
    directory, and a test that let it use the real one would leave directories behind on
    the machine running the suite and could collide with a real run.
    """
    return subprocess.run(
        [sys.executable, str(_ENGINE), *args],
        capture_output=True, text=True, encoding="utf-8", errors="replace", cwd=cwd,
        env={**os.environ, **env} if env else None,
    )


# A job in each mode, complete and well-formed. Every refusal test copies one and breaks
# exactly one thing, so a failure names the rule under test rather than a fixture drift.
# ``root`` must be absolute and the temp directory is only known at setUp, so the fixtures
# carry a placeholder that ``_JobCase.write`` fills with the real path.
ROOT = "<absolute root, filled in by _JobCase.write>"

FILE_JOB = {
    "problem": "Find every place the installer can leave a half-written file.",
    "root": ROOT,
    "exclude": [],
    "partition": "file",
    "lenses": ["bottom-up from the code", "top-down from the contract"],
}

SUBJECT_JOB = {
    "problem": "Find every place the installer can leave a half-written file.",
    "root": ROOT,
    "exclude": ["vendor/"],
    "partition": "subject",
    "lenses": ["bottom-up from the code", "top-down from the contract"],
    "areas": [
        {"name": "engine", "paths": ["engine/", "run.py"], "also_read": ["tests/test_engine.py"]},
        {"name": "docs", "paths": ["README.md", "docs/"], "lenses": ["a", "b", "c", "d"]},
        {"name": "rest", "paths": [], "remainder": True},
    ],
}


class _JobCase(unittest.TestCase):
    """A temp directory holding ``root/`` and a ``job.json`` the test writes."""

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.tmp = Path(self._tmp.name).resolve()
        self.root = self.tmp / "root"
        self.root.mkdir()
        self.job_path = self.tmp / "job.json"

    def tearDown(self):
        self._tmp.cleanup()

    def write(self, data) -> Path:
        if isinstance(data, dict) and data.get("root") == ROOT:
            data = dict(data, root=str(self.root))
        self.job_path.write_text(json.dumps(data), encoding="utf-8")
        return self.job_path

    def refuse(self, data, *fragments):
        """Assert ``load_job`` raises ``JobError`` and its message carries every fragment."""
        with self.assertRaises(review_panel.JobError) as ctx:
            review_panel.load_job(self.write(data))
        message = str(ctx.exception)
        for fragment in fragments:
            self.assertIn(fragment, message, message)
        return message

    def symlink(self, target, link):
        try:
            os.symlink(target, link)
        except (OSError, NotImplementedError) as exc:
            self.skipTest(f"cannot create a symlink here: {exc}")


class AWellFormedJobLoads(_JobCase):

    def test_file_mode_loads_with_nothing_defaulted(self):
        job = review_panel.load_job(self.write(FILE_JOB))
        self.assertEqual(job.problem, FILE_JOB["problem"])
        self.assertEqual(job.root, self.tmp / "root")
        self.assertEqual(job.partition, "file")
        self.assertEqual(job.exclude, ())
        self.assertEqual(job.lenses, tuple(FILE_JOB["lenses"]))
        self.assertEqual(job.areas, ())

    def test_subject_mode_loads_with_areas_as_declared(self):
        job = review_panel.load_job(self.write(SUBJECT_JOB))
        self.assertEqual(job.partition, "subject")
        self.assertEqual(job.exclude, ("vendor/",))
        self.assertEqual([a.name for a in job.areas], ["engine", "docs", "rest"])
        engine, docs, rest = job.areas
        self.assertEqual(engine.paths, ("engine/", "run.py"))
        self.assertEqual(engine.also_read, ("tests/test_engine.py",))
        self.assertFalse(engine.remainder)
        # An area without its own lens list inherits the job's; the engine writes nothing
        # into the area to say so, so ``None`` is the observable "absent".
        self.assertIsNone(engine.lenses)
        self.assertEqual(docs.lenses, ("a", "b", "c", "d"))
        self.assertTrue(rest.remainder)
        self.assertEqual(rest.paths, ())

    def test_a_relative_root_is_refused_naming_the_field(self):
        # The job file is written into the run directory and moves with it; a root
        # resolved against the file's own location would silently change the audited tree.
        for raw in ("root", "./root", "../root"):
            with self.subTest(root=raw):
                self.refuse(dict(FILE_JOB, root=raw), "'root'", "absolute")

    def test_a_prefix_is_told_from_a_file_by_its_trailing_slash(self):
        self.assertTrue(review_panel.is_prefix("engine/"))
        self.assertFalse(review_panel.is_prefix("engine"))


class AMissingFieldIsRefusedByName(_JobCase):

    def test_each_top_level_field(self):
        for field in ("problem", "root", "exclude", "partition", "lenses"):
            with self.subTest(field=field):
                data = dict(FILE_JOB)
                del data[field]
                self.refuse(data, "missing", f"'{field}'")

    def test_areas_is_required_in_subject_mode(self):
        data = dict(SUBJECT_JOB)
        del data["areas"]
        self.refuse(data, "missing", "'areas'")

    def test_an_area_field(self):
        for field in ("name", "paths"):
            with self.subTest(field=field):
                data = copy.deepcopy(SUBJECT_JOB)
                del data["areas"][0][field]
                self.refuse(data, "missing", f"'{field}'", "areas[0]")


