class AGlobCharacterIsRefused(_JobCase):

    def test_each_character_in_each_path_field(self):
        cases = [
            ("exclude", lambda d, p: d.__setitem__("exclude", [p])),
            ("areas[0].paths", lambda d, p: d["areas"][0].__setitem__("paths", [p])),
            ("areas[0].also_read", lambda d, p: d["areas"][0].__setitem__("also_read", [p])),
        ]
        for char in "*?[":
            for field, plant in cases:
                with self.subTest(char=char, field=field):
                    data = copy.deepcopy(SUBJECT_JOB)
                    plant(data, f"src/{char}.py")
                    self.refuse(data, field, "glob")


