class PathNormalisation(_JobCase):

    def test_dot_dot_is_refused(self):
        self.refuse(dict(FILE_JOB, exclude=["../secrets"]), "'exclude[0]'", "..")

    def test_a_leading_slash_is_refused(self):
        self.refuse(dict(FILE_JOB, exclude=["/etc/passwd"]), "'exclude[0]'")

    def test_a_drive_path_behind_a_dot_component_is_refused(self):
        # `.` components are dropped by normalization, so the absolute test must run on what
        # survives it: `./C:/x` tested raw looks relative and comes out `C:/x`, absolute on
        # Windows. Drive-relative `C:x` is refused the same way; it names another drive's
        # working directory, never a path under root.
        for raw in ("./C:/outside.py", ".\\C:\\outside.py", "././C:/outside.py",
                    "./C:outside.py"):
            for field, data in (("exclude", dict(FILE_JOB, exclude=[raw])),
                                ("areas[0].also_read", copy.deepcopy(SUBJECT_JOB))):
                if field != "exclude":
                    data["areas"][0]["also_read"] = [raw]
                with self.subTest(raw=raw, field=field):
                    self.refuse(data, f"'{field}[0]'", "absolute")

    def test_a_doubled_slash_is_not_absolute(self):
        job = review_panel.load_job(self.write(dict(FILE_JOB, exclude=[".//etc/passwd"])))
        self.assertEqual(job.exclude, ("etc/passwd",))

    def test_a_backslash_path_is_normalized(self):
        data = copy.deepcopy(SUBJECT_JOB)
        data["areas"][0]["paths"] = ["engine\\", ".\\run.py"]
        data["exclude"] = ["vendor\\lib\\"]
        job = review_panel.load_job(self.write(data))
        self.assertEqual(job.areas[0].paths, ("engine/", "run.py"))
        self.assertEqual(job.exclude, ("vendor/lib/",))

    def test_a_case_only_collision_is_refused(self):
        data = copy.deepcopy(SUBJECT_JOB)
        data["areas"][1]["paths"].append("Engine/")
        self.refuse(data, "case", "engine/", "Engine/")

    def test_a_case_only_collision_across_fields_is_refused(self):
        data = copy.deepcopy(SUBJECT_JOB)
        data["exclude"] = ["RUN.py"]
        self.refuse(data, "case", "run.py", "RUN.py")

    def test_also_read_outside_root_is_refused(self):
        for outside in ("../sibling/x.py", "/abs/x.py"):
            with self.subTest(path=outside):
                data = copy.deepcopy(SUBJECT_JOB)
                data["areas"][0]["also_read"] = [outside]
                self.refuse(data, "areas[0].also_read[0]")

    def test_a_file_and_prefix_ambiguity_is_refused(self):
        data = copy.deepcopy(SUBJECT_JOB)
        data["areas"][1]["paths"].append("engine")
        self.refuse(data, "engine", "engine/", "both")

    def test_the_root_itself_is_not_a_path(self):
        for raw in (".", "./", ""):
            with self.subTest(raw=raw):
                self.refuse(dict(FILE_JOB, exclude=[raw]), "'exclude[0]'")

    def test_root_must_be_a_directory(self):
        self.refuse(dict(FILE_JOB, root=str(self.tmp / "nowhere")), "'root'")


