class AFilesystemFailureIsAMessageNotATraceback(_JobCase):
    """Reading the job and inspecting the run directory touch the host; each way the host
    can refuse must come back as a ``JobError`` / ``RunDirError`` naming the path and the
    cause, so the CLI exits 2 with nothing written, never 1 with a traceback."""

    def test_invalid_utf8_job_bytes(self):
        self.job_path.write_bytes(b'\xff\xfe{"problem": "x"}')
        with self.assertRaises(review_panel.JobError) as ctx:
            review_panel.load_job(self.job_path)
        message = str(ctx.exception)
        self.assertIn(self.job_path.name, message)
        self.assertIn("UTF-8", message)

    def test_an_embedded_nul_in_root_is_a_refusal_not_a_value_error(self):
        # `Path.resolve` raises ValueError, not OSError, on a NUL byte; that one escaped
        # the wrapper as a traceback with exit 1.
        self.refuse(dict(FILE_JOB, root=str(self.root) + "/\u0000x"), "'root'", "resolve")

    def test_a_root_the_host_cannot_resolve(self):
        real = pathlib.Path.resolve

        def resolve(self, strict=False):
            if self.name == "root":
                raise OSError(errno.ELOOP, "Too many levels of symbolic links", str(self))
            return real(self, strict)

        with mock.patch.object(pathlib.Path, "resolve", resolve):
            self.refuse(FILE_JOB, "'root'", "symbolic links")

    def test_a_symlink_loop_root(self):
        # The live shape of the case above: before 3.13 ``resolve()`` raises RuntimeError on
        # a loop rather than OSError; from 3.13 it resolves and ``is_dir()`` is False. Both
        # must be the same refusal, naming the field.
        loop = self.tmp / "loop"
        try:
            os.symlink("loop", loop)
        except (OSError, NotImplementedError) as exc:
            self.skipTest(f"cannot create a symlink here: {exc}")
        self.refuse(dict(FILE_JOB, root=str(loop)), "'root'")

    @unittest.skipUnless(os.name == "posix", "a mode-000 directory is a POSIX shape")
    def test_an_unreadable_run_directory(self):
        if os.geteuid() == 0:
            self.skipTest("root reads a mode-000 directory")
        job = review_panel.load_job(self.write(FILE_JOB))
        rundir = self.tmp / "run"
        rundir.mkdir()
        rundir.chmod(0)
        try:
            with self.assertRaises(review_panel.RunDirError) as ctx:
                review_panel.check_rundir(rundir, job)
        finally:
            rundir.chmod(0o700)
        self.assertIn(str(rundir), str(ctx.exception))

    def test_the_cli_exits_2_and_writes_nothing(self):
        self.job_path.write_bytes(b'\xff\xfe{"problem": "x"}')
        proc = _run("plan", str(self.job_path), "--rundir", str(self.tmp / "run"))
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        self.assertIn("UTF-8", proc.stderr)
        self.assertNotIn("Traceback", proc.stderr)
        self.assertFalse((self.tmp / "run").exists(), "plan wrote before it was built")


class TheRunDirectory(_JobCase):
    """``plan`` refuses a run directory inside root or holding anything but the job."""

    def test_inside_root_is_refused(self):
        job = review_panel.load_job(self.write(FILE_JOB))
        with self.assertRaises(review_panel.RunDirError) as ctx:
            review_panel.check_rundir(self.tmp / "root" / "run", job)
        self.assertIn("inside", str(ctx.exception))

    def test_root_itself_is_refused(self):
        job = review_panel.load_job(self.write(FILE_JOB))
        with self.assertRaises(review_panel.RunDirError):
            review_panel.check_rundir(self.tmp / "root", job)

    def test_non_empty_is_refused_naming_what_is_there(self):
        job = review_panel.load_job(self.write(FILE_JOB))
        rundir = self.tmp / "run"
        rundir.mkdir()
        (rundir / "stale.txt").write_text("x", encoding="utf-8")
        with self.assertRaises(review_panel.RunDirError) as ctx:
            review_panel.check_rundir(rundir, job)
        self.assertIn("stale.txt", str(ctx.exception))

    def test_holding_only_the_job_file_is_accepted(self):
        rundir = self.tmp / "run"
        rundir.mkdir()
        self.job_path = rundir / "job.json"
        job = review_panel.load_job(self.write(FILE_JOB))
        review_panel.check_rundir(rundir, job)  # no raise

    def test_absent_is_accepted(self):
        job = review_panel.load_job(self.write(FILE_JOB))
        review_panel.check_rundir(self.tmp / "later", job)  # no raise

    def test_a_directory_nobody_can_examine_is_refused_rather_than_read_as_absent(self):
        """The pair with the test above, and the two must not be spelled the same. Absent
        means this stage may plan here; a path the host will not describe means nobody
        knows, and read as absent it plans a run into somebody else's directory. Probed
        through `os.lstat`, because that is what the guard asks now. What it must never go back
        to asking is `Path.exists` and its siblings, whose answer for a path they could not
        examine is a plain False on the interpreters that suppress the error — the same
        answer they give for a path that is not there."""
        job = review_panel.load_job(self.write(FILE_JOB))
        rundir = self.tmp / "run"
        rundir.mkdir()
        real = review_panel.os.lstat

        def refusing(path, *args, **kwargs):
            if pathlib.Path(path).name == rundir.name:
                raise PermissionError(errno.EACCES, "Permission denied", str(path))
            return real(path, *args, **kwargs)

        with mock.patch.object(review_panel.os, "lstat", refusing):
            with self.assertRaises(review_panel.RunDirError) as ctx:
                review_panel.check_rundir(rundir, job)
        self.assertIn(rundir.name, str(ctx.exception))
        self.assertIn("cannot examine", str(ctx.exception))

    def test_a_symlink_named_job_json_is_refused_even_when_it_resolves_to_the_job(self):
        # The one entry allowed is a regular file; a link is refused whatever it points at.
        job = review_panel.load_job(self.write(FILE_JOB))
        rundir = self.tmp / "run"
        rundir.mkdir()
        self.symlink(self.job_path, rundir / "job.json")
        with self.assertRaises(review_panel.RunDirError) as ctx:
            review_panel.check_rundir(rundir, job)
        self.assertIn("job.json", str(ctx.exception))
        self.assertIn("symlink", str(ctx.exception))

    def test_a_job_json_that_is_not_the_job_being_loaded_is_refused(self):
        job = review_panel.load_job(self.write(FILE_JOB))
        rundir = self.tmp / "run"
        rundir.mkdir()
        (rundir / "job.json").write_text("{}", encoding="utf-8")
        with self.assertRaises(review_panel.RunDirError) as ctx:
            review_panel.check_rundir(rundir, job)
        self.assertIn("job.json", str(ctx.exception))

    def test_a_symlink_to_the_job_under_any_other_name_is_refused_by_name(self):
        job = review_panel.load_job(self.write(FILE_JOB))
        rundir = self.tmp / "run"
        rundir.mkdir()
        self.symlink(self.job_path, rundir / "areas.json")
        with self.assertRaises(review_panel.RunDirError) as ctx:
            review_panel.check_rundir(rundir, job)
        self.assertIn("areas.json", str(ctx.exception))


